-- Mavi Giyim Treasury Simulation — database schema
-- SQLite. Every table that holds a number pulled from an external source
-- carries source_url / source and retrieved_at, so any figure can be traced
-- back to where it came from. Derived tables (ratios, exposure, hedge P&L)
-- are never hand-edited — they are (re)generated by Python scripts that read
-- the raw tables. Re-running a script should be safe (use INSERT OR REPLACE
-- keyed on the natural key, not blind INSERT).

PRAGMA foreign_keys = ON;

-- ---------------------------------------------------------------------
-- 0. Reference table
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS companies (
    company_id      INTEGER PRIMARY KEY,
    ticker          TEXT UNIQUE NOT NULL,      -- 'MAVI'
    name            TEXT NOT NULL,
    sector          TEXT
);

INSERT OR IGNORE INTO companies (company_id, ticker, name, sector)
VALUES (1, 'MAVI', 'Mavi Giyim Sanayi ve Ticaret A.S.', 'Apparel / Denim Retail');

-- ---------------------------------------------------------------------
-- 1. Step 2 — Financial baseline (raw, as extracted from KAP filings)
-- ---------------------------------------------------------------------
-- Long/tidy format on purpose: KAP statements have dozens of line items and
-- you will not need all of them. Store what you extract, add rows over time,
-- never need to alter table structure when you add a new line item.
CREATE TABLE IF NOT EXISTS financial_statements_raw (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    company_id      INTEGER NOT NULL REFERENCES companies(company_id),
    period_end      TEXT NOT NULL,          -- 'YYYY-MM-DD', e.g. 2025-06-30
    fiscal_year     INTEGER NOT NULL,
    fiscal_quarter  INTEGER NOT NULL,       -- 1-4
    statement_type  TEXT NOT NULL CHECK (statement_type IN ('BS','IS','CF')),
    line_item_en    TEXT NOT NULL,          -- standardized English label you choose, e.g. 'inventory'
    line_item_tr    TEXT,                   -- original KAP label, for traceability
    value_try       REAL NOT NULL,          -- always store in TRY, thousands or units — pick one and note it below
    unit            TEXT NOT NULL DEFAULT 'TRY',  -- 'TRY_thousand' or 'TRY' — be consistent across all rows
    source_url      TEXT NOT NULL,          -- direct KAP filing link
    filed_date      TEXT,                   -- date KAP published the filing
    retrieved_at    TEXT NOT NULL,          -- when you pulled/entered it (ISO datetime)
    UNIQUE(company_id, period_end, statement_type, line_item_en)
);

-- Derived ratios — one row per company per quarter, fully computed from the
-- raw table above by a Python script (never typed in by hand).
CREATE TABLE IF NOT EXISTS financial_ratios (
    id                  INTEGER PRIMARY KEY AUTOINCREMENT,
    company_id          INTEGER NOT NULL REFERENCES companies(company_id),
    period_end          TEXT NOT NULL,
    fiscal_year         INTEGER NOT NULL,
    fiscal_quarter      INTEGER NOT NULL,
    revenue             REAL,
    cogs                REAL,
    inventory           REAL,
    accounts_receivable REAL,
    accounts_payable    REAL,
    dio                 REAL,   -- Days Inventory Outstanding
    dso                 REAL,   -- Days Sales Outstanding
    dpo                 REAL,   -- Days Payable Outstanding
    ccc                 REAL,   -- Cash Conversion Cycle = DIO + DSO - DPO
    calculated_at       TEXT NOT NULL,
    calc_method_notes   TEXT,   -- e.g. 'DIO = inventory / cogs * days_in_quarter, quarterly not annualized'
    UNIQUE(company_id, period_end)
);

-- ---------------------------------------------------------------------
-- 2. Step 3 — FX rates (raw daily series from EVDS)
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS fx_rates (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    rate_date       TEXT NOT NULL,          -- 'YYYY-MM-DD'
    currency_pair   TEXT NOT NULL,          -- 'USDTRY' or 'EURTRY'
    rate_type       TEXT NOT NULL CHECK (rate_type IN ('buying','selling')),
    rate            REAL NOT NULL,
    source          TEXT NOT NULL DEFAULT 'TCMB EVDS',
    series_code     TEXT NOT NULL,          -- e.g. 'TP.DK.USD.A.YTL', for traceability
    retrieved_at    TEXT NOT NULL,
    UNIQUE(rate_date, currency_pair, rate_type)
);

-- Which balance sheet / cost items are FX-linked, and to what.
-- One row per (period, item) — lets exposure change over time as disclosure changes.
CREATE TABLE IF NOT EXISTS fx_exposure_items (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    company_id      INTEGER NOT NULL REFERENCES companies(company_id),
    period_end      TEXT NOT NULL,
    item_name       TEXT NOT NULL,          -- 'USD-linked cotton/fabric sourcing COGS', 'EUR trade payables', etc.
    exposure_type   TEXT NOT NULL CHECK (exposure_type IN ('balance_sheet','cash_flow')),
    balance_try     REAL NOT NULL,          -- TRY value of the exposed item at period end
    currency_linked TEXT NOT NULL,          -- 'USD' or 'EUR'
    direction       TEXT NOT NULL CHECK (direction IN ('asset_long_fx','liability_short_fx','cost_short_fx')),
    -- asset_long_fx: TRY value rises when FX rises (e.g. FX receivable)
    -- liability_short_fx / cost_short_fx: TRY value/cost rises when FX rises (payable, import cost)
    notes           TEXT,
    source          TEXT NOT NULL,          -- KAP filing, footnote reference, or your own estimation method
    UNIQUE(company_id, period_end, item_name)
);

-- ---------------------------------------------------------------------
-- 3. Step 4 — Hedging policy backtest
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS hedge_scenarios (
    id                  INTEGER PRIMARY KEY AUTOINCREMENT,
    company_id          INTEGER NOT NULL REFERENCES companies(company_id),
    scenario_name       TEXT NOT NULL,      -- 'unhedged', 'forward_100pct', 'collar_75pct'
    period_start        TEXT NOT NULL,
    period_end          TEXT NOT NULL,
    currency_pair        TEXT NOT NULL,
    notional_try_at_risk REAL NOT NULL,     -- from fx_exposure_items, the amount being hedged
    instrument_type      TEXT NOT NULL CHECK (instrument_type IN ('none','forward','option_collar')),
    strike_rate           REAL,             -- forward rate or collar strike
    collar_floor          REAL,             -- for option_collar only
    collar_cap             REAL,            -- for option_collar only
    premium_cost_try       REAL DEFAULT 0,
    result_pnl_try          REAL,           -- computed: what this scenario would have made/lost vs. spot
    calculated_at           TEXT NOT NULL,
    calc_method_notes       TEXT
);

-- ---------------------------------------------------------------------
-- 4. Step 5 — Financing structure comparison
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS financing_structures (
    id                  INTEGER PRIMARY KEY AUTOINCREMENT,
    structure_name      TEXT NOT NULL,      -- 'Letter of Credit', 'Open Account', 'Factoring', 'Supply Chain Finance'
    description          TEXT,
    typical_cost_pct_pa  REAL,              -- annualized cost assumption, cite source in notes
    typical_tenor_days   INTEGER,
    liquidity_impact_notes TEXT,
    source                TEXT              -- where the cost assumption came from (bank rate sheet, TCMB, academic source)
);

CREATE TABLE IF NOT EXISTS financing_comparison (
    id                  INTEGER PRIMARY KEY AUTOINCREMENT,
    company_id          INTEGER NOT NULL REFERENCES companies(company_id),
    period_end          TEXT NOT NULL,
    structure_id         INTEGER NOT NULL REFERENCES financing_structures(id),
    ccc_days_assumed      REAL,             -- from financial_ratios for this period
    working_capital_try   REAL,
    estimated_cost_try     REAL,
    calculated_at           TEXT NOT NULL
);

-- ---------------------------------------------------------------------
-- 5. Step 6/7 — Monthly report log (so you have a dated track record)
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS monthly_reports (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    company_id      INTEGER NOT NULL REFERENCES companies(company_id),
    report_month    TEXT NOT NULL,          -- 'YYYY-MM'
    generated_at    TEXT NOT NULL,
    file_path       TEXT,                   -- path to the pdf/xlsx/pptx artifact
    summary_notes   TEXT,                   -- your 3-5 sentence write-up, stored here too
    UNIQUE(company_id, report_month)
);
CREATE TABLE IF NOT EXISTS interest_rates_raw (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    period TEXT NOT NULL,          -- 'YYYY-MM'
    currency TEXT NOT NULL,        -- 'TRY' | 'USD' | 'EUR'
    tenor TEXT NOT NULL,           -- '3M'
    rate_pct REAL NOT NULL,        -- annualized, e.g. 49.42
    series_code TEXT NOT NULL,
    source_url TEXT NOT NULL,
    retrieved_at TEXT NOT NULL,
    UNIQUE(period, currency, tenor)
);
CREATE TABLE IF NOT EXISTS hedging_backtest_results (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    company_id INTEGER NOT NULL,
    period_end TEXT NOT NULL,           -- exposure snapshot date = hedge start basis
    currency_linked TEXT NOT NULL,
    direction TEXT NOT NULL,
    native_amount_k REAL NOT NULL,      -- derived: balance_try / spot at period_end
    spot_at_hedge_start REAL NOT NULL,
    hedge_end TEXT,                     -- next quarter's period_end; NULL if not yet disclosed
    spot_at_hedge_end REAL,             -- NULL if pending
    days_n INTEGER NOT NULL,
    try_rate_pct REAL NOT NULL,
    fx_rate_pct REAL NOT NULL,
    forward_rate REAL NOT NULL,
    pnl_forward_vs_unhedged_try REAL,   -- NULL if pending; positive = forward hedge outperformed
    unhedged_pnl_try REAL,
    status TEXT NOT NULL CHECK (status IN ('settled','pending')),
    calculated_at TEXT NOT NULL,
    UNIQUE(company_id, period_end, currency_linked, direction)
);
CREATE TABLE IF NOT EXISTS options_collar_results (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    company_id INTEGER NOT NULL,
    period_end TEXT NOT NULL,
    currency_linked TEXT NOT NULL,
    direction TEXT NOT NULL,
    native_amount_k REAL NOT NULL,
    forward_rate REAL NOT NULL,
    realized_vol_annualized REAL NOT NULL,
    k_factor REAL NOT NULL,
    call_strike REAL NOT NULL,
    put_strike REAL NOT NULL,
    hedge_end TEXT,
    spot_at_hedge_end REAL,
    settlement_rate REAL,
    pnl_collar_vs_unhedged_try REAL,
    status TEXT NOT NULL CHECK (status IN ('settled','pending')),
    calculated_at TEXT NOT NULL,
    UNIQUE(company_id, period_end, currency_linked, direction, k_factor)
);
CREATE TABLE IF NOT EXISTS financing_rates_raw (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    period TEXT NOT NULL,             -- 'YYYY-MM'
    rate_type TEXT NOT NULL CHECK (rate_type IN ('commercial_loan','factoring','lc_commission')),
    rate_pct REAL NOT NULL,
    series_code TEXT,
    source_url TEXT NOT NULL,
    notes TEXT,
    retrieved_at TEXT NOT NULL,
    UNIQUE(period, rate_type)
);

CREATE TABLE IF NOT EXISTS financing_scenario_results (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    company_id INTEGER NOT NULL,
    period_end TEXT NOT NULL,
    fiscal_year INTEGER NOT NULL,
    fiscal_quarter INTEGER NOT NULL,
    days_in_quarter INTEGER NOT NULL,
    inventory REAL NOT NULL,
    accounts_receivable REAL NOT NULL,
    accounts_payable REAL NOT NULL,
    commercial_loan_rate_pct REAL NOT NULL,
    factoring_rate_pct REAL NOT NULL,
    lc_commission_rate_pct REAL NOT NULL,
    baseline_wc_financing_cost_try REAL NOT NULL,
    factoring_ar_cost_try REAL NOT NULL,
    factoring_vs_baseline_ar_saving_try REAL NOT NULL,
    lc_ap_cost_try REAL NOT NULL,
    scf_ap_cost_try REAL NOT NULL,
    lc_vs_scf_ap_saving_try REAL,
    lc_scf_comparison_note TEXT,
    calculated_at TEXT NOT NULL,
    UNIQUE(company_id, period_end)
);
